#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct KMP {
    string pattern;
    vector<int> fail;
    KMP(const string &p) : pattern(p) {
        int m = p.size();
        fail.assign(m + 1, 0);
        int j = 0;
        for (int i = 1; i < m; ++i) {
            while (j > 0 && p[i] != p[j]) j = fail[j];
            if (p[i] == p[j]) ++j;
            fail[i + 1] = j;
        }
    }
    int nextState(int state, char c) {
        while (state > 0 && pattern[state] != c) state = fail[state];
        if (pattern[state] == c) ++state;
        return state;
    }
};

int main() {
    int n;
    string s;
    cin >> n >> s;
    int m = s.size();
    KMP kmp(s);
    vector<vector<ll>> dp(n + 1, vector<ll>(m + 1, 0));
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int state = 0; state <= m; ++state) {
            if (dp[i][state] == 0) continue;
            for (char c : {'0', '1'}) {
                int next_state = kmp.nextState(state, c);
                if (next_state < m) {
                    dp[i + 1][next_state] += dp[i][state];
                }
            }
        }
    }
    ll total = 1LL << n;
    ll bad = 0;
    for (int state = 0; state < m; ++state) {
        bad += dp[n][state];
    }
    cout << total - bad << endl;
    return 0;
}
