#include <string>
using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;
    int m = s.length();

    if (m == 0) {
        cout << (1LL << n) << endl;
        return 0;
    }

    // Compute KMP failure function
    vector<int> fail(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = fail[i-1];
        while (j > 0 && s[i] != s[j]) {
            j = fail[j-1];
        }
        if (s[i] == s[j]) {
            j++;
        }
        fail[i] = j;
    }

    // Compute transition table for KMP automaton
    vector<vector<int>> trans(m+1, vector<int>(2, 0));
    for (int state = 0; state <= m; ++state) {
        for (int c = 0; c < 2; ++c) {
            char ch = '0' + c;
            if (state < m && s[state] == ch) {
                trans[state][c] = state + 1;
            } else {
                if (state == 0) {
                    trans[state][c] = 0;
                } else {
                    trans[state][c] = trans[fail[state-1]][c];
                }
            }
        }
    }

    // DP to count strings that do NOT contain s in any rotation
    vector<vector<long long>> dp(n+1, vector<long long>(m, 0));
    dp[0][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (int state = 0; state < m; ++state) {
            if (dp[i][state] == 0) continue;
            for (int c = 0; c < 2; ++c) {
                int next_state = trans[state][c];
                if (next_state < m) {
                    dp[i+1][next_state] += dp[i][state];
                }
            }
        }
    }

    long long total = (1LL << n);
    long long invalid = 0;
    for (int state = 0; state < m; ++state) {
        invalid += dp[n][state];
    }

    cout << (total - invalid) << endl;

    return 0;
}
