```cpp
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct KMP {
    string pat;
    vector<int> fail;
    KMP(string p) : pat(p), fail(p.size() + 1) {
        fail[0] = -1;
        int i = 0, j = -1;
        while (i < (int)p.size()) {
            while (j != -1 && p[i] != p[j]) j = fail[j];
            i++; j++;
            fail[i] = (j == 0 ? -1 : j);
        }
    }
    // returns the next state given current state and next char
    int next(int state, char c) {
        while (state != -1 && (state == (int)pat.size() || pat[state] != c)) state = fail[state];
        return state + 1;
    }
};

int main() {
    int n;
    string s;
    cin >> n >> s;
    int m = s.size();
    KMP kmp(s);
    // dp[pos][state] = number of ways
    vector<vector<ll>> dp(n + 1, vector<ll>(m + 1));
    dp[0][0] = 1;
    for (int i = 0; i < n; i++) {
        for (int st = 0; st <= m; st++) {
            if (dp[i][st] == 0) continue;
            for (char c : {'0', '1'}) {
                int nst = kmp.next(st, c);
                if (nst <= m) dp[i + 1][nst] += dp[i][st];
            }
        }
    }
    ll total = 1LL << n;
    ll bad = 0;
    for (int st = 0; st < m; st++) bad += dp[n][st];
    cout << total - bad << endl;
    return 0;
}
