To solve this problem, we need to determine the number of distinct cyclical binary strings of length \( n \) that contain a given binary string \( s \) as a substring. The solution involves using dynamic programming (DP) combined with the KMP (Knuth-Morris-Pratt) algorithm to efficiently track the state of substring matching.

### Approach
1. **KMP Failure Function**: Compute the failure function (partial match table) for the string \( s \) to handle efficient backtracking during substring matching.
2. **Transition Table**: Precompute a transition table that helps determine the next state in the KMP automaton when a character is added to the current state.
3. **Dynamic Programming**: Use a DP approach where each state represents the current position in the string and the current state in the KMP automaton. The DP tracks the number of valid strings that avoid containing \( s \) as a substring.
4. **Inclusion-Exclusion Principle**: Calculate the total number of binary strings of length \( n \) and subtract the number of strings that do not contain \( s \) as a substring to get the result.

### Solution Code
```cpp
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;
    int m = s.length();

    if (m == 0) {
        cout << (1LL << n) << endl;
        return 0;
    }

    // Compute failure function (partial match table)
    vector<int> fail(m, 0);
    for (int i = 1; i < m; ++i) {
        int j = fail[i - 1];
        while (j > 0 && s[i] != s[j]) {
            j = fail[j - 1];
        }
        if (s[i] == s[j]) {
            j++;
        }
        fail[i] = j;
    }

    // Precompute transition table
    vector<vector<int>> trans(m, vector<int>(2, 0));
    for (int state = 0; state < m; ++state) {
        for (int c = 0; c < 2; ++c) {
            char ch = '0' + c;
            int j = state;
            while (j > 0 && ch != s[j]) {
                j = fail[j - 1];
            }
            if (ch == s[j]) {
                j++;
            }
            trans[state][c] = j;
        }
    }

    // DP to count strings that do NOT contain s as a substring
    vector<vector<long long>> dp(n + 1, vector<long long>(m, 0));
    dp[0][0] = 1;

    for (int i = 0; i < n; ++i) {
        for (int state = 0; state < m; ++state) {
            if (dp[i][state] == 0) continue;
            for (int c = 0; c < 2; ++c) {
                int next_state = trans[state][c];
                if (next_state < m) {
                    dp[i + 1][next_state] += dp[i][state];
                }
            }
        }
    }

    long long total = 1LL << n;
    long long invalid = 0;
    for (int state = 0; state < m; ++state) {
        invalid += dp[n][state];
    }

    cout << (total - invalid) << endl;

    return 0;
}
