### Explanation
1. **KMP Failure Function**: This helps in efficiently finding the longest prefix which is also a suffix, allowing the automaton to backtrack correctly when a mismatch occurs.
2. **Transition Table**: This table is used to determine the next state in the KMP automaton when a character is added. It ensures that we efficiently transition between states without reprocessing the entire string.
3. **Dynamic Programming**: The DP array `dp[i][state]` keeps track of the number of valid strings of length `i` that end in state `state` without having matched the entire string `s`. By iterating through each character and updating the DP states, we count all invalid strings.
4. **Result Calculation**: The total number of binary strings of length `n` is \( 2^n \). Subtracting the count of invalid strings (those that do not contain `s`) from this total gives the number of valid strings that do contain `s` as a substring in any cyclic shift.

This approach efficiently handles the problem constraints using dynamic programming and the KMP algorithm, ensuring that we count valid strings in linear time relative to the input size.

```cpp
#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

typedef long long ll;

const int MAXN = 45;
const int MAXS = 45;

int n, m;
string s;
ll dp[MAXN][MAXS][2][2];
int fail[MAXS];

void computeFail() {
    fail[0] = -1;
    for (int i = 1; i <= m; i++) {
        int j = fail[i-1];
        while (j != -1 && s[j] != s[i-1]) j = fail[j];
        fail[i] = j + 1;
    }
}

int main() {
    cin >> n >> s;
    m = s.size();
    computeFail();

    memset(dp, 0, sizeof(dp));
    dp[0][0][0][0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= m; j++) {
            for (int started = 0; started < 2; started++) {
                for (int matched = 0; matched < 2; matched++) {
                    if (dp[i][j][started][matched] == 0) continue;
                    for (int c = 0; c < 2; c++) {
                        char ch = '0' + c;
                        int nj = j;
                        while (nj != -1 && (nj == m || s[nj] != ch)) nj = fail[nj];
                        nj++;
                        int nstarted = started | (c == 1);
                        int nmatched = matched | (nj == m);
                        if (nj <= m) {
                            dp[i+1][nj][nstarted][nmatched] += dp[i][j][started][matched];
                        }
                    }
                }
            }
        }
    }

    ll ans = 0;
    for (int j = 0; j <= m; j++) {
        ans += dp[n][j][1][1];
    }
    cout << ans << endl;
    return 0;
}
