To solve this problem, we need to count the number of distinct binary strings of length `n` that contain a given substring `s` when considering all possible cyclical shifts of the string. 

### Approach
1. **Problem Analysis**: The key insight is that a cyclical binary string `t` of length `n` contains `s` as a substring if there exists any rotation of `t` such that `s` is a substring of that rotation. This can be rephrased as checking if `s` is a substring of `t + t` (the concatenation of `t` with itself), which effectively considers all possible rotations of `t`.

2. **Inclusion-Exclusion Principle**: Instead of directly counting the valid strings, we use the inclusion-exclusion principle. We first compute the total number of binary strings of length `n` (which is `2^n`) and then subtract the number of strings that do not contain `s` as a substring in any rotation.

3. **KMP Algorithm**: To efficiently check for the presence of `s` in all rotations of `t`, we use the Knuth-Morris-Pratt (KMP) algorithm. This helps in building a state machine that tracks the longest prefix of `s` that matches the suffix of the current string being built.

4. **Dynamic Programming (DP)**: We use a DP approach where `dp[i][j]` represents the number of strings of length `i` that end in a state `j` (where `j` is the length of the longest prefix of `s` matched so far). The transitions between states are determined using the KMP failure function.

5. **Circular Check**: Since the string is cyclical, we need to ensure that the substring `s` does not appear in any rotation. This is handled by checking all possible starting positions in the concatenated string `t + t` and ensuring that no valid occurrence of `s` exists.

### Solution Code
```cpp
#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> computeLPS(const string& s) {
    int n = s.length();
    vector<int> lps(n, 0);
    for (int i = 1, len = 0; i < n; ) {
        if (s[i] == s[len]) {
            lps[i++] = ++len;
        } else if (len > 0) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }
    return lps;
}

int main() {
    int n;
    string s;
    cin >> n >> s;
    int m = s.length();
    if (m > n) {
        cout << 0 << endl;
        return 0;
    }
    if (m == 0) {
        cout << (1LL << n) << endl;
        return 0;
    }

    vector<int> lps = computeLPS(s);

    // Build transition table for KMP automaton
    vector<vector<int>> trans(m + 1, vector<int>(2, 0));
    for (int state = 0; state <= m; ++state) {
        for (int c = 0; c < 2; ++c) {
            if (state < m && s[state] == ('0' + c)) {
                trans[state][c] = state + 1;
            } else if (state == 0) {
                trans[state][c] = 0;
            } else {
                trans[state][c] = trans[lps[state - 1]][c];
            }
        }
    }

    // DP to count strings of length n that do not contain s in any rotation
    // We need to consider all possible starting points in the circular string
    // This is handled by checking all possible initial states and ensuring no full match occurs

    // First, compute the number of linear strings of length n that do not contain s
    vector<vector<long long>> dp(n + 1, vector<long long>(m + 1, 0));
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (dp[i][j] == 0) continue;
            for (int c = 0; c < 2; ++c) {
                int next_state = trans[j][c];
                if (next_state < m) {
                    dp[i + 1][next_state] += dp[i][j];
                }
            }
        }
    }

    long long linear_no = 0;
    for (int j = 0; j < m; ++j) {
        linear_no += dp[n][j];
    }

    // Now, handle the circular case
    // We need to subtract strings that contain s in any rotation
    // This requires checking all possible starting positions
    // Use inclusion-exclusion with DP for circular strings

    // For circular strings, we need to consider all possible starting states
    // and ensure that no rotation contains s

    // Compute the number of circular strings that do not contain s in any rotation
    // This is done by considering all possible starting states and transitions

    vector<vector<long long>> circ_dp(n + 1, vector<long long>(m + 1, 0));
    for (int start = 0; start < m; ++start) {
        circ_dp[0][start] = 1;
    }

    for (int i = 0; i < n; ++i) {
        vector<vector<long long>> next_dp(m + 1, vector<long long>(m + 1, 0));
        for (int start = 0; start < m; ++start) {
            for (int state = 0; state <= m; ++state) {
                if (circ_dp[i][state] == 0) continue;
                for (int c = 0; c < 2; ++c) {
                    int next_state = trans[state][c];
                    if (next_state < m) {
                        next_dp[start][next_state] += circ_dp[i][state];
                    }
                }
            }
        }
        circ_dp = next_dp;
    }

    long long circular_no = 0;
    for (int start = 0; start < m; ++start) {
        for (int state = 0; state < m; ++state) {
            circular_no += circ_dp[n][state];
        }
    }

    // The answer is total strings minus circular_no
    long long total = 1LL << n;
    cout << (total - circular_no) << endl;

    return 0;
}
```

### Explanation
1. **LPS Array**: The `computeLPS` function computes the Longest Prefix Suffix (LPS) array for the string `s`, which is used to build the transition table for the KMP automaton.

2. **Transition Table**: The transition table `trans` is built using the LPS array. This table helps in determining the next state in the KMP automaton when a character is added to the current string.

3. **Linear DP**: The first DP (`dp`) calculates the number of linear strings of length `n` that do not contain `s` as a substring. This is used to handle the non-circular case.

4. **Circular DP**: The second DP (`circ_dp`) handles the circular case by considering all possible starting states and ensuring that no rotation of the string contains `s`. This is done by iterating over all possible starting states and transitions.

5. **Result Calculation**: The final result is obtained by subtracting the number of circular strings that do not contain `s` from the total number of binary strings of length `n`.

This approach efficiently handles the problem constraints using dynamic programming and the KMP algorithm, ensuring that all possible rotations are considered.

```cpp
#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

const int MAXN = 45;
const int MAXS = 45;

int n, m;
char s[MAXS];
int fail[MAXS];

void computeFail() {
    fail[0] = -1;
    int k = -1;
    for (int i = 1; i <= m; i++) {
        while (k >= 0 && s[k + 1] != s[i]) k = fail[k];
        if (s[k + 1] == s[i]) k++;
        fail[i] = k;
    }
}

long long dp[MAXN][MAXS][2];

int main() {
    cin >> n;
    cin >> (s + 1);
    m = strlen(s + 1);
    computeFail();

    memset(dp, 0, sizeof(dp));
    dp[0][0][0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= m; j++) {
            for (int matched = 0; matched < 2; matched++) {
                if (dp[i][j][matched] == 0) continue;
                for (int c = 0; c < 2; c++) {
                    char ch = '0' + c;
                    int nj = j;
                    while (nj >= 0 && s[nj + 1] != ch) nj = fail[nj];
                    if (s[nj + 1] == ch) nj++;
                    int nmatched = matched;
                    if (nj == m) nmatched = 1;
                    if (nj > m) nj = m;
                    dp[i + 1][nj][nmatched] += dp[i][j][matched];
                }
            }
        }
    }

    long long ans = 0;
    for (int j = 0; j <= m; j++) {
        ans += dp[n][j][1];
    }
    cout << ans << endl;
    return 0;
}
